-- requires: realizer
-- base_render_corpus — the numbers-repo rendering oracle, imported verbatim: per (collection, fiber, element) the
-- three notation spellings (katex/unicode/asciimath) + breadcrumb + notes. RAW — `collection` is numbers' key
-- (singular/naming can differ from ours) and addresses are untranslated. A DATA seed for per-collection triage
-- against our render codecs (NOT wired as pass/fail assertions). See https://github.com/enumeratio/enumeratio/wiki/Port-Inventory.
-- Generated from ~/Playground/ideas/numbers/db/seeds/collection_examples.tsv — do not hand-edit.
CREATE TABLE base_render_corpus (
  family_path text NOT NULL, collection text NOT NULL, element_address text,   -- element_address NULL ⇒ a fiber-header row
  katex text, unicode text, asciimath text, breadcrumb text, notes text, redirected_paths text);

-- coverage: the corpus collection keys mapped to our collections. Match is heuristic (exact, or the numbers-repo
-- singular key + 's'/'es'); `mapped` NULL means no realized collection here yet (address translation is later).
CREATE VIEW base_render_corpus_coverage AS
  SELECT c.collection AS numbers_key, count(*) AS rows,
         count(*) FILTER (WHERE c.element_address IS NOT NULL) AS element_rows,
         coalesce(x.id, s.id, e.id) AS mapped
  FROM base_render_corpus c
       LEFT JOIN base_collection x ON x.id = c.collection
       LEFT JOIN base_collection s ON s.id = c.collection || 's'
       LEFT JOIN base_collection e ON e.id = c.collection || 'es'
  GROUP BY c.collection, coalesce(x.id, s.id, e.id);

    SELECT count(*)::text FROM base_render_corpus $q$);
